const CACHE_PREFIX = 'prism-breaker-release-';
const CACHE_NAME = CACHE_PREFIX + VERSION;
const PIN_CACHE = 'prism-breaker-client-pins-v1';
const COMPLETE_PATH = '/__prism_pwa_complete__';
const paths = new Set(PRECACHE.map(asset => asset.path));
const pins = new Map();
const identifying = new Map();
let installing;
const absolute = path => new URL(path, self.location.origin).href;
const pinPath = id => absolute('/__prism_pwa_client__/' + encodeURIComponent(id));

const releaseVersion = version => typeof version === 'string' && /^[a-f0-9]{20}$/.test(version);
const validPin = version => version === 'network' || releaseVersion(version);
async function readJSON(response) { try { return response ? await response.json() : null; } catch { return null; } }

async function complete(version) {
  if (!releaseVersion(version)) return false;
  try {
    const name = CACHE_PREFIX + version;
    const marker = await readJSON(await caches.match(absolute(COMPLETE_PATH), {cacheName: name}));
    if (marker?.version !== version || !Number.isSafeInteger(marker.files) || marker.files < 1) return false;
    const cache = await caches.open(name);
    const keys = new Set((await cache.keys()).map(request => request.url));
    const inventory = version === VERSION ? [...paths] : marker.paths;
    if (inventory) return Array.isArray(inventory) && inventory.length === marker.files && inventory.every(path => typeof path === 'string' && path.startsWith('/') && keys.has(absolute(path)));
    // Older releases stored a count rather than paths. Their caches contain only
    // verified assets and this marker; retain compatibility without trusting a marker alone.
    return keys.has(absolute('/index.html')) && keys.size === marker.files + 1;
  } catch { return false; }
}

async function rememberClient(id, version) {
  if (!id || !validPin(version)) return false;
  pins.set(id, version);
  try {
    const store = await caches.open(PIN_CACHE);
    await store.put(pinPath(id), new Response(JSON.stringify({version}), {headers: {'Content-Type': 'application/json'}}));
  } catch { /* Keep the in-memory identity; readiness is checked separately. */ }
  return true;
}

async function clientVersion(id) {
  if (!id) return VERSION;
  if (pins.has(id)) return pins.get(id);
  try {
    const record = await readJSON(await caches.match(pinPath(id), {cacheName: PIN_CACHE}));
    const version = record?.version;
    if (validPin(version)) {
      pins.set(id, version);
      return version;
    }
  } catch { /* Ask the page if its persisted pin was lost. Never guess the latest release. */ }
  if (identifying.has(id)) return identifying.get(id);
  const identification = (async () => {
    const client = await self.clients.get(id);
    if (!client) return null;
    const version = await new Promise(resolve => {
      const channel = new MessageChannel();
      const finish = value => { clearTimeout(timer); channel.port1.close(); resolve(validPin(value) ? value : null); };
      const timer = setTimeout(() => finish(null), 1500);
      channel.port1.onmessage = event => finish(event.data?.version);
      try { client.postMessage({type:'PWA_VERSION_REQUEST'}, [channel.port2]); } catch { finish(null); }
    });
    if (version) await rememberClient(id, version);
    return version;
  })().catch(() => null);
  identifying.set(id, identification);
  try { return await identification; } finally { identifying.delete(id); }
}

async function download(asset, cache, controller) {
  const timer = setTimeout(() => controller.abort(new Error('Offline asset download timed out: ' + asset.path)), 20000);
  try {
    controller.signal.throwIfAborted();
    const url = new URL(asset.url || asset.path, self.location.origin);
    url.searchParams.set('__prism_release', VERSION);
    const response = await fetch(url.href, {cache: 'reload', credentials: 'same-origin', signal: controller.signal});
    if (response.status !== 200 || response.type === 'opaque' || response.redirected) {
      throw new Error('Offline download failed: ' + asset.path);
    }
    if (asset.path === '/index.html') {
      // Pagelove serializes HTML on write; verify its release identity instead of raw bytes.
      const html = await response.clone().text();
      const marker = new RegExp('<meta\\b(?=[^>]*\\bname=["\']prism-release["\'])(?=[^>]*\\bcontent=["\']' + VERSION + '["\'])[^>]*>', 'i');
      if (!response.headers.get('content-type')?.includes('text/html') || !marker.test(html)) {
        throw new Error('Offline document belongs to a different release');
      }
    } else {
      const digest = await crypto.subtle.digest('SHA-256', await response.clone().arrayBuffer());
      const hash = Array.from(new Uint8Array(digest), byte => byte.toString(16).padStart(2, '0')).join('');
      if (hash !== asset.sha256) throw new Error('Offline asset changed during download: ' + asset.path);
    }
    controller.signal.throwIfAborted();
    await cache.put(absolute(asset.path), response);
  } finally { clearTimeout(timer); }
}

async function prepareOfflineCache() {
  if (installing) return installing;
  installing = (async () => {
    if (await complete(VERSION)) return;
    const cache = await caches.open(CACHE_NAME);
    const controller = new AbortController();
    const deadline = setTimeout(() => controller.abort(new Error('Offline release download timed out.')), 75000);
    try {
      await cache.delete(absolute(COMPLETE_PATH));
      // Bound simultaneous downloads and wait for every write before removing a failed cache.
      for (let offset = 0; offset < PRECACHE.length; offset += 6) {
        const batch = await Promise.allSettled(PRECACHE.slice(offset, offset + 6).map(asset => download(asset, cache, controller)));
        const failed = batch.find(result => result.status === 'rejected');
        if (failed) throw failed.reason;
      }
      controller.signal.throwIfAborted();
      await cache.put(absolute(COMPLETE_PATH), new Response(JSON.stringify({version: VERSION, savedAt: Date.now(), files: PRECACHE.length, paths: [...paths]}), {headers: {'Content-Type': 'application/json'}}));
    } catch (error) {
      try { await caches.delete(CACHE_NAME); } catch { /* Preserve the original failure. */ }
      throw error;
    } finally { clearTimeout(deadline); }
  })();
  try { await installing; } finally { installing = null; }
}

self.addEventListener('install', event => {
  // Updates intentionally wait. The start screen offers the explicit restart action.
  event.waitUntil(prepareOfflineCache());
});

async function pruneUnusedReleases() {
  const windows = await self.clients.matchAll({type: 'window', includeUncontrolled: true});
  const store = await caches.open(PIN_CACHE);
  const inUse = new Set([VERSION]);
  const liveIds = new Set(windows.map(client => client.id));
  let unknownClient = false;
  for (const client of windows) {
    const record = await readJSON(await store.match(pinPath(client.id)));
    if (!validPin(record?.version)) { unknownClient = true; continue; }
    inUse.add(record.version);
  }
  // An unregistered or older page may still be loading: preserve its possible release.
  if (unknownClient) return;
  const releases = [];
  for (const name of await caches.keys()) {
    const version = name.slice(CACHE_PREFIX.length);
    if (!name.startsWith(CACHE_PREFIX) || !releaseVersion(version)) continue;
    const marker = await readJSON(await caches.match(absolute(COMPLETE_PATH), {cacheName: name}));
    releases.push({name, version, savedAt: marker?.version === version && Number.isFinite(marker.savedAt) ? marker.savedAt : 0});
  }
  // Retain one previous release as a fallback, plus every release used by an open tab.
  releases.sort((a, b) => b.savedAt - a.savedAt);
  for (const release of releases.slice(0, 2)) inUse.add(release.version);
  for (const release of releases) if (!inUse.has(release.version)) await caches.delete(release.name);
  for (const request of await store.keys()) {
    const id = decodeURIComponent(new URL(request.url).pathname.split('/').pop());
    if (!liveIds.has(id)) await store.delete(request);
  }
}

self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    try { await pruneUnusedReleases(); } catch { /* Optional cleanup must not prevent activation. */ }
    await self.clients.claim();
  })());
});

self.addEventListener('message', event => {
  const data = event.data;
  if (!data || typeof data !== 'object') return;
  if (data.type === 'SKIP_WAITING') {
    event.waitUntil((async () => {
      try { await prepareOfflineCache(); await self.skipWaiting(); }
      catch { /* The requesting page times out with a retry action; keep the old worker. */ }
    })());
  } else if (data.type === 'CLIENT_VERSION') {
    event.waitUntil((async () => {
      const ready = validPin(data.version) && (data.version === 'network' || await complete(data.version));
      // A fresh network document must keep using network modules until its complete
      // release exists. Older pinned tabs keep their identity even after cache eviction.
      let existing = pins.get(event.source?.id);
      if (!existing) try { existing = (await readJSON(await caches.match(pinPath(event.source?.id), {cacheName: PIN_CACHE})))?.version; } catch {}
      if (ready || existing !== 'network') await rememberClient(event.source?.id, data.version);
      event.ports[0]?.postMessage({type: 'PWA_STATUS', version: VERSION, clientVersion: data.version, ready});
    })());
  } else if (data.type === 'GET_STATUS') {
    event.waitUntil((async () => {
      const version = await clientVersion(event.source?.id);
      event.ports[0]?.postMessage({type: 'PWA_STATUS', version: VERSION, clientVersion: version, ready: await complete(version)});
    })());
  } else if (data.type === 'REPAIR_CACHE') {
    event.waitUntil((async () => {
      try {
        if (data.version !== VERSION) throw new Error('A newer game release is available. Reload to download it.');
        await prepareOfflineCache();
        await rememberClient(event.source?.id, VERSION);
        event.ports[0]?.postMessage({type: 'PWA_STATUS', version: VERSION, clientVersion: VERSION, ready: true});
      } catch (error) {
        event.ports[0]?.postMessage({type: 'PWA_STATUS', version: VERSION, clientVersion: data.version, ready: false, error: error.message});
      }
    })());
  }
});

self.addEventListener('fetch', event => {
  const request = event.request;
  const url = new URL(request.url);
  // Selector responses, score reads and writes remain exclusively owned by Pagelove.
  if (request.method !== 'GET' || url.origin !== self.location.origin || request.headers.has('range') || url.pathname.startsWith('/__qa/') || url.pathname.startsWith('/worlds/') || url.pathname.startsWith('/editor/') || url.pathname === '/scores.html' || url.pathname === '/worlds.html') return;
  const navigation = request.mode === 'navigate' && (url.pathname === '/' || url.pathname === '/index.html');
  const immutable = url.pathname.match(/^\/releases\/([a-f0-9]{20})(\/.*)$/);
  const logicalPath = immutable ? immutable[2] : url.pathname;
  // A still-open older tab may request a lazy module removed from the latest release.
  const staticPath = url.pathname !== '/sw.js' && (/^\/assets\//.test(url.pathname) || /^\/vendor\//.test(url.pathname) || /\.(?:js|css|webmanifest|ico|svg|png)$/.test(url.pathname));
  if (!navigation && !paths.has(logicalPath) && !staticPath) return;
  event.respondWith((async () => {
    const version = navigation ? VERSION : await clientVersion(event.clientId);
    if (navigation && event.resultingClientId) await rememberClient(event.resultingClientId, version);
    // Storage can be evicted independently of registration. Only a newly loaded document
    // may recover from the network; an already-running release must never mix its modules.
    if (version === 'network') return fetch(request, {cache:'no-store'});
    // A release URL is an identity, not an alias for whichever worker is active.
    if (immutable && immutable[1] !== version) return new Response('This file belongs to another game release. Reload Prism Breaker.', {status:503});
    let cached;
    try {
      if (version && (!navigation || await complete(version))) cached = await caches.match(absolute(navigation ? '/index.html' : logicalPath), {cacheName: CACHE_PREFIX + version});
    } catch { /* An online navigation can recover even if CacheStorage is unavailable. */ }
    if (cached) return cached;
    if (releaseVersion(version) && (navigation || paths.has(logicalPath))) {
      try {
        const cache = await caches.open(CACHE_PREFIX + version);
        await cache.delete(absolute(COMPLETE_PATH));
      } catch { /* The missing-cache response remains actionable. */ }
    }
    if (navigation) {
      try {
        const response = await fetch(request);
        if (response.ok && event.resultingClientId) await rememberClient(event.resultingClientId, 'network');
        return response;
      } catch { /* A plain offline message below still permits a later online reload. */ }
    }
    // Immutable URLs remain coherent even after cache eviction or while a newer
    // worker controls a page whose older complete cache never existed here.
    // Fetch only the exact requested identity; never substitute a root alias.
    if (immutable && immutable[1] === version) {
      try { const response=await fetch(request,{cache:'no-store'});if(response.ok&&!response.redirected)return response; } catch {}
    }
    // Never splice a new network module into an older running game if storage was evicted.
    return new Response('The offline game download is incomplete. Reconnect and reload Prism Breaker.', {status: 503, headers: {'Content-Type': 'text/plain; charset=utf-8'}});
  })());
});
